package com.example.product;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
public class Product {
    @Id
    private Long id;

    private String name;

    private int price;

    private int stock;

    protected Product() {
    }

    public void rename(String name) {
        this.name = name;
    }

    public void changePrice(int price) {
        this.price = price;
    }

    public void reserve(int amount) {
        if (stock < amount) {
            throw new OutOfStockException(id);
        }
        stock -= amount;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public int getPrice() {
        return price;
    }
}

package com.example.product;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ProductService {
    private final ProductRepository productRepository;

    public ProductService(ProductRepository productRepository) {
        this.productRepository = productRepository;
    }

    @Transactional
    public ProductResponse update(long id, UpdateProductRequest request) {
        Product product = productRepository.findById(id).orElseThrow(() -> new ProductNotFoundException(id));
        product.rename(request.name());
        product.changePrice(request.price());
        return ProductResponse.from(product);
    }

    @Transactional
    public void reserve(long id, int amount) {
        Product product = productRepository.findById(id).orElseThrow(() -> new ProductNotFoundException(id));
        product.reserve(amount);
    }
}

package com.example.product;

public record UpdateProductRequest(String name, int price) {
}

package com.example.product;

public record ProductResponse(long id, String name, int price) {
    static ProductResponse from(Product product) {
        return new ProductResponse(product.getId(), product.getName(), product.getPrice());
    }
}

