import jakarta.persistence.Version;

@Version
private Long version;

public Long getVersion() {
    return version;
}

package com.example.product;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class ConflictHandler {
    @ExceptionHandler(ObjectOptimisticLockingFailureException.class)
    public ProblemDetail handleConflict(ObjectOptimisticLockingFailureException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, "Someone else changed this product. Reload and try again.");
    }
}

@Transactional
public ProductResponse update(long id, UpdateProductRequest request) {
    Product product = productRepository.findById(id).orElseThrow(() -> new ProductNotFoundException(id));
    if (product.getVersion() != request.version()) {
        throw new ObjectOptimisticLockingFailureException(Product.class, id);
    }
    product.rename(request.name());
    product.changePrice(request.price());
    productRepository.flush();
    return ProductResponse.from(product);
}

package com.example.product;

import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Component;

@Component
public class StockReserver {
    private static final int MAX_ATTEMPTS = 3;

    private final ProductService productService;

    public StockReserver(ProductService productService) {
        this.productService = productService;
    }

    public void reserve(long id, int amount) {
        for (int attempt = 1; ; attempt++) {
            try {
                productService.reserve(id, amount);
                return;
            } catch (ObjectOptimisticLockingFailureException e) {
                if (attempt >= MAX_ATTEMPTS) {
                    throw e;
                }
            }
        }
    }
}
